class Solution {
public:
    bool differByOne(vector<string>& dict) {
        int m = dict[0].size();
        for (int j = 0; j < m; j++) {
            unordered_set<string> seen;
            for (const string& w : dict) {
                string pat = w;
                pat[j] = '*';
                if (seen.count(pat)) return true;
                seen.insert(pat);
            }
        }
        return false;
    }
};

class Solution {
    public boolean differByOne(String[] dict) {
        int m = dict[0].length();
        for (int j = 0; j < m; j++) {
            Set<String> seen = new HashSet<>();
            for (String w : dict) {
                String pat = w.substring(0, j) + "*" + w.substring(j + 1);
                if (seen.contains(pat)) return true;
                seen.add(pat);
            }
        }
        return false;
    }
}

var differByOne = function(dict) {
    const m = dict[0].length;
    for (let j = 0; j < m; j++) {
        const seen = new Set();
        for (const w of dict) {
            const pat = w.slice(0, j) + '*' + w.slice(j + 1);
            if (seen.has(pat)) return true;
            seen.add(pat);
        }
    }
    return false;
};
